INSERT INTO ai_logs (id, user_id, chuc_nang, input_tom_tat, output_text, thoi_gian) VALUES (42, 1, 'tro_ly_ao', '[Quản trị viên Hệ thống] Hỏi: Xin chào bạn, tôi muốn hỏi số dư', '[Rule-Based] Chào Quản trị viên Hệ thống! Hiện tại số dư tín dụng học tập trong ví của bạn là 100.0 giờ. Bạn có thể dùng số giờ này để đặt lịch học kỹ năng mới cùng bạn bè trên Chợ kỹ năng nhé!', '2026-10-08 23:54:28');
INSERT INTO ai_logs (id, user_id, chuc_nang, input_tom_tat, output_text, thoi_gian) VALUES (43, 1, 'tro_ly_ao', '[Quản trị viên Hệ thống] Hỏi: Chào bạn', 'Chào bạn! Tôi là trợ lý AI học đường của TimeBank EDU, rất vui được hỗ trợ bạn hôm nay.', '2026-10-08 23:54:28');
