INSERT INTO ai_logs (id, user_id, chuc_nang, input_tom_tat, output_text, thoi_gian) VALUES (45, 1, 'tro_ly_ao', '[Quản trị viên Hệ thống] Hỏi: Bạn có thể giới thiệu về TimeBank không?', '[Rule-Based] Chào Quản trị viên Hệ thống! Tôi là Trợ lý Học đường TimeBank EDU (Hỗ trợ bởi AI Gemini). Số dư ví hiện tại của bạn là 100.0h. Bạn có thể hỏi tôi về: số dư giờ, lịch học sắp tới, hướng dẫn đăng kỹ năng hoặc gợi ý lộ trình học tập!', '2026-10-08 23:54:48');
INSERT INTO ai_logs (id, user_id, chuc_nang, input_tom_tat, output_text, thoi_gian) VALUES (46, 1, 'tro_ly_ao', '[Quản trị viên Hệ thống] Hỏi: Chào bạn', 'Chào bạn! Tôi là trợ lý AI học đường của TimeBank EDU, rất vui được hỗ trợ bạn hôm nay.', '2026-10-08 23:54:48');
INSERT INTO blog_posts (id, tieu_de, noi_dung, anh_minh_hoa, tac_gia_ai, trang_thai, thoi_gian_dang) VALUES (1, 'Khởi động Mô hình Ngân hàng Thời gian Học đường: Một giờ bạn dạy - Một giờ bạn học', 'Chào mừng toàn thể Thầy Cô giáo và các bạn học sinh đến với TimeBank EDU! Tại đây, mọi tri thức đều bình đẳng, 1 giờ dạy đổi lấy 1 giờ học. Hãy cùng nhau chia sẻ thế mạnh và giúp đỡ bạn bè cùng tiến bộ nhé!', '/static/img/newsletter_banner.svg', 0, 'da_dang', '2026-10-01 08:00:00');
INSERT INTO chat_messages (id, user_id, vai_tro, noi_dung, thoi_gian) VALUES (1, 3, 'user', 'Em muốn học thêm kỹ năng giao tiếp tiếng Anh thì nên tìm bạn nào?', '2026-10-01 09:00:00');
INSERT INTO chat_messages (id, user_id, vai_tro, noi_dung, thoi_gian) VALUES (2, 3, 'assistant', 'Chào An! Dựa trên hệ thống, bạn Lê Kim Chi (10A3) đang chia sẻ kỹ năng Luyện phản xạ IELTS Speaking rất phù hợp với em nhé!', '2026-10-01 09:00:05');
INSERT INTO community_tasks (id, tieu_de, mo_ta, dia_diem, so_gio_thuong, so_luong_toi_da, han_dang_ky, nguoi_tao_id, trang_thai, thoi_gian_tao) VALUES (1, 'Dọn rác bãi biển Hạ Long sáng Chủ nhật', 'Hoạt động thanh niên tình nguyện thu gom rác thải nhựa tại bờ biển, làm sạch cảnh quan môi trường.', 'Bãi tắm Bãi Cháy, TP. Hạ Long', 2.0, 10, '2026-10-25', 2, 'mo_dang_ky', '2026-10-05 08:00:00');
INSERT INTO community_tasks (id, tieu_de, mo_ta, dia_diem, so_gio_thuong, so_luong_toi_da, han_dang_ky, nguoi_tao_id, trang_thai, thoi_gian_tao) VALUES (2, 'Hỗ trợ thư viện trường sắp xếp sách', 'Phân loại sách giáo khoa mới, dán mã định danh và sắp xếp lên giá sách theo chuẩn thư viện xanh.', 'Phòng Thư viện - Tầng 2', 1.5, 5, '2026-10-20', 2, 'mo_dang_ky', '2026-10-05 08:30:00');
INSERT INTO community_tasks (id, tieu_de, mo_ta, dia_diem, so_gio_thuong, so_luong_toi_da, han_dang_ky, nguoi_tao_id, trang_thai, thoi_gian_tao) VALUES (3, 'Dạy kỹ năng số cho các em khối Tiểu học', 'Phụ đạo tin học, hướng dẫn các em học sinh lớp 3-4 gõ bàn phím 10 ngón và tra cứu tài liệu học tập an toàn.', 'Phòng máy Tin học số 2', 2.0, 4, '2026-10-30', 2, 'mo_dang_ky', '2026-10-05 09:00:00');
INSERT INTO community_tasks (id, tieu_de, mo_ta, dia_diem, so_gio_thuong, so_luong_toi_da, han_dang_ky, nguoi_tao_id, trang_thai, thoi_gian_tao) VALUES (4, 'Hỗ trợ số hóa tài liệu thư viện trường', 'Quét và phân loại sách tham khảo vào hệ thống thư viện điện tử.', 'Phòng Thư viện - Tầng 2', 2.0, 4, '2026-10-15', 2, 'hoan_thanh', '2026-10-04 08:00:00');
