INSERT INTO quiz_questions (id, session_id, cau_hoi, lua_chon_a, lua_chon_b, lua_chon_c, lua_chon_d, dap_an_dung) VALUES (1, 1, 'Khái niệm góc giữa hai mặt phẳng trong không gian được đo bằng góc giữa:', 'Hai đường thẳng bất kỳ trên hai mặt phẳng', 'Hai đường thẳng lần lượt vuông góc với giao tuyến tại cùng một điểm', 'Hai vectơ chỉ phương ngẫu nhiên', 'Giao tuyến của hai mặt phẳng', 'B');
INSERT INTO quiz_questions (id, session_id, cau_hoi, lua_chon_a, lua_chon_b, lua_chon_c, lua_chon_d, dap_an_dung) VALUES (2, 1, 'Khi hai mặt phẳng vuông góc với nhau, góc giữa chúng bằng bao nhiêu độ?', '0 độ', '45 độ', '90 độ', '180 độ', 'C');
INSERT INTO quiz_questions (id, session_id, cau_hoi, lua_chon_a, lua_chon_b, lua_chon_c, lua_chon_d, dap_an_dung) VALUES (3, 1, 'Để tính khoảng cách từ một điểm M đến mặt phẳng (P), ta cần dựng:', 'Đoạn vuông góc kẻ từ M đến mặt phẳng (P)', 'Một đường thẳng xiên bất kỳ', 'Đường thẳng song song với (P)', 'Đoạn nối M với trọng tâm tam giác đáy', 'A');
INSERT INTO quiz_questions (id, session_id, cau_hoi, lua_chon_a, lua_chon_b, lua_chon_c, lua_chon_d, dap_an_dung) VALUES (4, 1, 'Cho hình chóp S.ABC có SA vuông góc với đáy (ABC). Góc giữa đường thẳng SB và đáy là:', 'Góc SBA', 'Góc SAB', 'Góc ASB', 'Góc SCB', 'A');
INSERT INTO quiz_questions (id, session_id, cau_hoi, lua_chon_a, lua_chon_b, lua_chon_c, lua_chon_d, dap_an_dung) VALUES (5, 1, 'Tuyệt chiêu nhận diện nhanh góc giữa mặt bên và mặt đáy trong hình chóp đều là gì?', 'Xác định trung điểm cạnh đáy rồi nối với đỉnh', 'Kẻ bừa một đường thẳng nối tâm đáy', 'Không thể xác định', 'Dùng thước đo độ trên giấy', 'A');
INSERT INTO quiz_questions (id, session_id, cau_hoi, lua_chon_a, lua_chon_b, lua_chon_c, lua_chon_d, dap_an_dung) VALUES (6, 2, 'Hợp âm Đô trưởng (C) cơ bản gồm những nốt nào trong âm giai?', 'Đô - Mi - Son (C - E - G)', 'Đô - Rê - Mi (C - D - E)', 'La - Đô - Mi (A - C - E)', 'Son - Si - Rê (G - B - D)', 'A');
INSERT INTO quiz_questions (id, session_id, cau_hoi, lua_chon_a, lua_chon_b, lua_chon_c, lua_chon_d, dap_an_dung) VALUES (7, 2, 'Khi bấm hợp âm La thứ (Am), ngón trỏ thường đặt ở vị trí nào?', 'Ngăn 1 dây 2 (nốt Đô)', 'Ngăn 2 dây 3', 'Ngăn 3 dây 1', 'Ngăn 1 dây 6', 'A');
INSERT INTO quiz_questions (id, session_id, cau_hoi, lua_chon_a, lua_chon_b, lua_chon_c, lua_chon_d, dap_an_dung) VALUES (8, 2, 'Điệu Disco cơ bản thường có nhịp phách như thế nào?', 'Nhịp 2/4 hoặc 4/4 rộn rã, dứt khoát', 'Nhịp 3/4 êm dịu điệu Valse', 'Nhịp 6/8 chậm rãi', 'Không có nhịp phách cố định', 'A');
INSERT INTO quiz_questions (id, session_id, cau_hoi, lua_chon_a, lua_chon_b, lua_chon_c, lua_chon_d, dap_an_dung) VALUES (9, 2, 'Bí quyết để chuyển nhanh giữa các hợp âm mà không bị vấp tiếng là gì?', 'Giữ ngón tay sát phím đàn và tìm ngón chung làm trụ', 'Nhấc toàn bộ cả bàn tay ra thật xa cần đàn', 'Dừng gảy 5 giây để nhìn tay', 'Bấm thật mạnh cho đau ngón tay', 'A');
INSERT INTO quiz_questions (id, session_id, cau_hoi, lua_chon_a, lua_chon_b, lua_chon_c, lua_chon_d, dap_an_dung) VALUES (10, 2, 'Khi ngón tay bị đau lúc mới tập guitar, cách khắc phục khoa học nhất là:', 'Tập đều đặn mỗi ngày 20-30 phút để hình thành vết chai tự nhiên', 'Bỏ đàn 2 tháng', 'Dùng băng keo quấn kín các đầu ngón tay', 'Bôi dầu hỏa vào ngón tay', 'A');
INSERT INTO quiz_questions (id, session_id, cau_hoi, lua_chon_a, lua_chon_b, lua_chon_c, lua_chon_d, dap_an_dung) VALUES (11, 3, 'Trong bài thi IELTS Speaking Part 1, độ dài lý tưởng cho mỗi câu trả lời là:', 'Khoảng 2 đến 3 câu hoàn chỉnh có mở rộng ý tự nhiên', 'Chỉ trả lời đúng ''Yes'' hoặc ''No''', 'Nói độc thoại liên tục 10 phút', 'Im lặng mỉm cười chờ giám khảo hỏi tiếp', 'A');
INSERT INTO quiz_questions (id, session_id, cau_hoi, lua_chon_a, lua_chon_b, lua_chon_c, lua_chon_d, dap_an_dung) VALUES (12, 3, 'Để nâng cao điểm tiêu chí Từ vựng (Lexical Resource), bạn nên sử dụng:', 'Collocations và từ đồng nghĩa ngữ cảnh tự nhiên', 'Từ cổ điển thế kỷ 18 khó hiểu', 'Từ viết tắt tiếng lóng tin nhắn', 'Lặp lại 1 từ duy nhất nhiều lần', 'A');
INSERT INTO quiz_questions (id, session_id, cau_hoi, lua_chon_a, lua_chon_b, lua_chon_c, lua_chon_d, dap_an_dung) VALUES (13, 3, 'Khi gặp câu hỏi bất ngờ trong Speaking Part 1, chiến thuật câu giờ thông minh là:', 'Dùng filler phrase tự nhiên như ''That’s an interesting question...''', 'Nói to ''I don''t know'' rồi ngồi im', 'Xin phép giám khảo tra từ điển Google', 'Hỏi ngược lại giám khảo', 'A');
INSERT INTO quiz_questions (id, session_id, cau_hoi, lua_chon_a, lua_chon_b, lua_chon_c, lua_chon_d, dap_an_dung) VALUES (14, 3, 'Tiêu chí ''Fluency and Coherence'' (Trôi chảy và mạch lạc) đánh giá điều gì?', 'Khả năng diễn đạt liên tục, có liên kết ý logic, ít ngập ngừng kéo dài', 'Nói thật nhanh như đọc ráp dù sai ngữ pháp', 'Giọng điệu phải giống 100% người bản xứ', 'Số lượng từ ngữ phát âm to nhất', 'A');
INSERT INTO quiz_questions (id, session_id, cau_hoi, lua_chon_a, lua_chon_b, lua_chon_c, lua_chon_d, dap_an_dung) VALUES (15, 3, 'Bí quyết tự tin luyện nói tiếng Anh hằng ngày cùng bạn bè là gì?', 'Tạo môi trường trao đổi thoải mái, không sợ mắc lỗi sai', 'Chỉ nói khi thuộc lòng 100% kịch bản', 'Chỉ luyện nói một mình trước gương trong bóng tối', 'Không bao giờ nói chuyện với ai', 'A');
